import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const VILLES = ['Tunis', 'Sfax', 'Sousse', 'Monastir', 'Gabès', 'Bizerte', 'Ariana'];
const NIVEAUX = ['Primaire', 'Collège', 'Lycée 1ère', 'Lycée 2ème', 'Lycée 3ème (Bac)', 'Université'];

export default function Profile() {
  const { user } = useAuth();
  const [form, setForm] = useState({ user_prenom: '', user_nom: '', ville: '', niveau: '', telephone: '', bio: '' });
  const [loading, setLoading] = useState(true);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    const route = user?.role === 'professeur' ? '/api/professeurs/me' : '/api/etudiants/me';
    api.get(route).then(r => {
      setForm(r.data);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, [user]);

  async function handleSave() {
    try {
      const route = user?.role === 'professeur' ? '/api/professeurs/me' : '/api/etudiants/me';
      // Synchronisation des noms de champs pour le backend
      const payload = {
        ...form,
        nom: form.user_nom,
        prenom: form.user_prenom
      };
      await api.put(route, payload);
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
    } catch (e) { alert('Erreur lors de la sauvegarde'); }
  }

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '12px 14px', fontSize: '.9rem', width: '100%', outline: 'none' };

  if (loading) return <div style={{ padding: 40, textAlign: 'center' }}>Chargement du profil...</div>;

  return (
    <div style={{ padding: 32, maxWidth: 800, margin: '0 auto' }}>
      <h2 style={{ fontFamily: 'Syne', marginBottom: 24 }}>👤 Mon Profil</h2>

      <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 30 }}>
        {/* Identité */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20, marginBottom: 20 }}>
          <div>
            <label style={{ fontSize: '.8rem', color: 'var(--text2)', display: 'block', marginBottom: 6 }}>Prénom</label>
            <input style={inp} value={form.user_prenom || ''} onChange={e => setForm({ ...form, user_prenom: e.target.value })} />
          </div>
          <div>
            <label style={{ fontSize: '.8rem', color: 'var(--text2)', display: 'block', marginBottom: 6 }}>Nom</label>
            <input style={inp} value={form.user_nom || ''} onChange={e => setForm({ ...form, user_nom: e.target.value })} />
          </div>
        </div>

        {/* Ville et Niveau */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20, marginBottom: 20 }}>
          <div>
            <label style={{ fontSize: '.8rem', color: 'var(--text2)', display: 'block', marginBottom: 6 }}>Ville</label>
            <select style={inp} value={form.ville || ''} onChange={e => setForm({ ...form, ville: e.target.value })}>
              <option value="">Choisissez votre ville</option>
              {VILLES.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          {user?.role === 'étudiant' && (
            <div>
              <label style={{ fontSize: '.8rem', color: 'var(--text2)', display: 'block', marginBottom: 6 }}>Niveau scolaire</label>
              <select style={inp} value={form.niveau || ''} onChange={e => setForm({ ...form, niveau: e.target.value })}>
                <option value="">Choisissez votre niveau</option>
                {NIVEAUX.map(n => <option key={n} value={n}>{n}</option>)}
              </select>
            </div>
          )}
        </div>

        {/* Autres infos */}
        <div style={{ marginBottom: 20 }}>
          <label style={{ fontSize: '.8rem', color: 'var(--text2)', display: 'block', marginBottom: 6 }}>Téléphone</label>
          <input style={inp} placeholder="+216 ..." value={form.telephone || ''} onChange={e => setForm({ ...form, telephone: e.target.value })} />
        </div>

        <div style={{ marginBottom: 30 }}>
          <label style={{ fontSize: '.8rem', color: 'var(--text2)', display: 'block', marginBottom: 6 }}>Bio / À propos</label>
          <textarea style={{ ...inp, height: 100, resize: 'none' }} value={form.bio || ''} onChange={e => setForm({ ...form, bio: e.target.value })} />
        </div>

        <button onClick={handleSave} style={{ width: '100%', padding: 14, background: '#6c63ff', color: '#fff', border: 'none', borderRadius: 12, fontWeight: 600, cursor: 'pointer' }}>
          {saved ? '✅ Profil enregistré !' : 'Enregistrer les modifications'}
        </button>
      </div>
    </div>
  );
}
